import java.util.*;
public class Muli{
     public static int Muli(int a,int b) 
    {
        int product=a*b;
        return product;
    

    } 
    public static void main(String[] args) {
        int a=3;
        int b=4;
        int prod=a*b;
        Muli(a,b); 
        System.out.println(prod);
    }
}